    'Value' => 'Valor',
    'Until (UTC)' => 'Hasta (UTC)',
    'Unblock' => 'Desbloquear',
    'None.' => 'Ninguno.',
    'already blocked' => 'ya bloqueado',
    'asked for an admin role' => 'pide rol de administrador',
    'role that does not exist' => 'rol que no existe',
    'filled the trap field' => 'rellenó el campo trampa',
    'forged page stamp' => 'sello falsificado',
    'never loaded the page' => 'no cargó la página',
    'too fast' => 'demasiado rápido',
    'random username' => 'usuario aleatorio',
